import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate, Link, useLocation } from 'react-router-dom'; // Import useLocation
import { useGoogleLogin } from '@react-oauth/google';

const Login = () => {
    const [gmail, setGmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const navigate = useNavigate();
    const location = useLocation(); // Initialize useLocation

    const handleLogin = async (e) => {
        e.preventDefault();
        setError(''); // Clear previous errors

        try {
            const response = await axios.post('http://localhost:8082/api/auth/login', {
                gmail,
                password
            });

            if (response.data) {
                console.log("User Data from Login:", response.data);
                const userData = response.data;
                localStorage.setItem('userRole', userData.role);
                localStorage.setItem('username', userData.username);
                localStorage.setItem('token', userData.jwt);
                localStorage.setItem('profilePictureUrl', userData.profilePictureUrl);
                window.dispatchEvent(new Event('localStorageUpdated')); // Dispatch event
                // Navigate based on previous location or to home
                if (location.state?.from) {
                    navigate(location.state.from);
                } else {
                    navigate('/');
                }
            } else {
                alert("Login Failed. Please check your credentials.");
            }

        } catch (error) {
            console.error("An error occurred during login:", error);
            alert("An error occurred. Could not connect to the server.");
        }
    };

     const handleGoogleLogin = useGoogleLogin({
    onSuccess: async (tokenResponse) => {
      console.log("onSuccess callback entered.");
      try {
        const response = await fetch('http://localhost:8082/api/auth/google', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ token: tokenResponse.access_token })
        });

        if (response.ok) {
          const userData = await response.json();
          console.log("User Data from Google Login:", userData);
          localStorage.setItem('userRole', userData.role);
          localStorage.setItem('username', userData.username);
          localStorage.setItem('token', userData.jwt);
          localStorage.setItem('profilePictureUrl', userData.profilePictureUrl);
          window.dispatchEvent(new Event('localStorageUpdated')); // Dispatch event
          // Navigate based on previous location or to home
          if (location.state?.from) {
              navigate(location.state.from);
          } else {
              navigate('/');
          }
        } else {
          alert("Google Login Failed.");
        }
      } catch (error) {
        console.error("An error occurred during Google login:", error);
        alert("An error occurred during Google login.");
      }
    },
    onError: () => {
      alert('Google Login Failed');
    },
  });

    return (
        <div style={{ maxWidth: '450px', margin: '5rem auto', padding: '2rem', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', borderRadius: '12px' }}>
            <h2 style={{ textAlign: 'center', marginBottom: '1.5rem' }}>Login</h2>
            <form onSubmit={handleLogin}>
                <div style={{ marginBottom: '1rem' }}>
                    <label>Email</label>
                    <input
                        type="email"
                        className="search-input" // Re-using your CSS class
                        style={{ width: '100%', padding: '0.75rem', marginTop: '0.25rem', background: '#f3f4f6' }}
                        placeholder="your.email@example.com"
                        value={gmail}
                        onChange={(e) => setGmail(e.target.value)}
                        required
                    />
                </div>
                <div style={{ marginBottom: '1.5rem' }}>
                    <label>Password</label>
                    <input
                        type="password"
                        className="search-input"
                        style={{ width: '100%', padding: '0.75rem', marginTop: '0.25rem', background: '#f3f4f6' }}
                        placeholder="Password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                    />
                </div>
                {error && <p style={{ color: '#ef4444', textAlign: 'center', marginBottom: '1rem' }}>{error}</p>}
                <button type="submit" className="btn-primary" style={{ width: '100%', border: 'none' }}>
                    Login
                </button>
                <button onClick={() => handleGoogleLogin()} className="btn-secondary" style={{ width: '100%', border: 'none', marginTop: '1rem' }}>
                    Sign in with Google
                </button>
                <p style={{ textAlign: 'center', marginTop: '1rem' }}>
                    Don't have an account? <Link to="/register" style={{ color: '#10b981' }}>Register here</Link>
                </p>
            </form>
        </div>
    );
}

export default Login;
